package com.zerotrust.internalresource.exception;
import com.zerotrust.internalresource.audit.RequestContextFilter;import com.zerotrust.internalresource.dto.ErrorResponse;import com.zerotrust.internalresource.service.ResourceNotFoundException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(ResourceNotFoundException.class)public ResponseEntity<ErrorResponse> notFound(ResourceNotFoundException exception,HttpServletRequest request){return error(HttpStatus.NOT_FOUND,"RESOURCE_NOT_FOUND",exception.getMessage(),request);}@ExceptionHandler(MethodArgumentNotValidException.class)public ResponseEntity<ErrorResponse> invalid(MethodArgumentNotValidException exception,HttpServletRequest request){return error(HttpStatus.BAD_REQUEST,"INVALID_ARGUMENT","request validation failed",request);}@ExceptionHandler(Exception.class)public ResponseEntity<ErrorResponse> unexpected(Exception exception,HttpServletRequest request){return error(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_ERROR","internal resource service error",request);}private ResponseEntity<ErrorResponse> error(HttpStatus status,String code,String message,HttpServletRequest request){return ResponseEntity.status(status).body(new ErrorResponse(false,code,message,(String)request.getAttribute(RequestContextFilter.TRACE_ID_ATTRIBUTE)));}}
